13	function toCodePoints(input: string): number[] {
14	  const codepoints = [];
15	  const size = input.length;
16	
17	  for (let i = 0; i < size; i += 1) {
18	    const before = input.charCodeAt(i);
19	
20	    if (before >= 0xd800 && before <= 0xdbff && size > i + 1) {
21	      const next = input.charCodeAt(i + 1);
22	
23	      if (next >= 0xdc00 && next <= 0xdfff) {
24	        codepoints.push((before - 0xd800) * 0x400 + next - 0xdc00 + 0x10000);
25	        i += 1;
26	        continue;
27	      }
28	    }
29	
30	    codepoints.push(before);
31	  }
32	
33	  return codepoints;
34	}
