59	  /**
60	   * the "commonly mapped to nothing" characters [StringPrep, B.1]
61	   * that can be mapped to nothing.
62	   */
63	  const mapping2nothing = commonly_mapped_to_nothing;
64	
65	  if (typeof input !== 'string') {
66	    throw new TypeError('Expected string.');
67	  }
68	
69	  if (input.length === 0) {
70	    return '';
