74	  const mapped_input = toCodePoints(input)
75	    // 1.1 mapping to space
76	    .map((character) => (mapping2space.get(character) ? 0x20 : character))
77	    // 1.2 mapping to nothing
78	    .filter((character) => !mapping2nothing.get(character));
