    v6: rawCidrs.v6.map((cidr) => [new ipaddr.IPv6(cidr[0]), cidr[1]]),
  };
}

async function hasAWSCname(host: string) {
  try {
    const addresses = await dnsResolveCname(host);
    return addresses.some((address) => address.endsWith('.amazonaws.com'));
