68	  async function handler(instance: StoredInstance) {
69	    try {
70	      const cluster = await MongoCluster.deserialize(instance.serialized);
71	      await cluster.withClient(
72	        () => {
73	          // connect and close
74	        },
75	        { serverSelectionTimeoutMS: 2000 },
76	      );
