97	  argv: {
98	    id?: string;
99	    runnerDir: string;
100	  } & MongoClusterOptions,
101	  args: string[],
102	) {
103	  let mongodArgs: string[];
104	  let execArgs: string[];
105	
106	  const doubleDashIndex = args.indexOf('--');
107	  if (doubleDashIndex !== -1) {
108	    mongodArgs = args.slice(0, doubleDashIndex);
109	    execArgs = args.slice(doubleDashIndex + 1);
110	  } else {
111	    mongodArgs = [];
112	    execArgs = args;
113	  }
114	  const cluster = await MongoCluster.start({
115	    ...argv,
116	    args: mongodArgs,
117	  });
118	  try {
119	    const [prog, ...progArgs] = execArgs;
120	    const child = spawn(prog, progArgs, {
121	      stdio: 'inherit',
122	      env: {
123	        ...process.env,
124	        // both spellings since otherwise I'd end up misspelling these half of the time
125	        MONGODB_URI: cluster.connectionString,
126	        MONGODB_URL: cluster.connectionString,
127	        MONGODB_HOSTPORT: cluster.hostport,
128	      },
129	    });
